/** DML_VERKAUFSPOSITIONEN_BY_DM_R_1391925_PP { pk(dt_month, Region) } **/
DML_VERKAUFSPOSITIONEN_BY_DM_R_1391925_PP as (
select
    t1.dt_month,
    t2.Region,
    t2.Umsatz,
    t2.Umsatz as Vormonatsumsatz
from #DML_OPTION_DTMONTH t1
inner join #DML_VERKAUFSPOSITIONEN_BY_DM_R_24FB925E t2
    on t2.dt_month = dateadd(month, -1, cast(t1.dt_month as date))
)


/*-----------------------------------------------------*/
/**                       query                       **/
/*-----------------------------------------------------*/

select
    coalesce(t1.Region, t2.Region) as Region,
    t1.Umsatz,
    t1.UmsatzAbgeschlossenerBestellungen,
    t2.Vormonatsumsatz,
    t3d770.DurchschnittsumsatzJeKunde,
    t1.UmsatzanteilAllerRegionen
from (select * from #DML_VERKAUFSPOSITIONEN_BY_DM_R_24FB925E where dt_month in (select dt_month from #DML_OPTION_DTMONTH)) t1
full outer join DML_VERKAUFSPOSITIONEN_BY_DM_R_1391925_PP t2
    on (t2.dt_month = t1.dt_month or (t2.dt_month is null and t1.dt_month is null))
    and (t2.Region = t1.Region or (t2.Region is null and t1.Region is null))
left join DML_VERKAUFSPOSITIONEN_BY_DM_R_24FBE49 t3d770 
	on (t3d770.dt_month = t1.dt_month or (t3d770.dt_month is null and t1.dt_month is null))
	and (t3d770.Region = t1.Region or (t3d770.Region is null and t1.Region is null))
order by Region;
